class Solution {
public:
    int LIS(vector<int>& nums) {
        int n = nums.size();
        vector<int>tails;
        for(int i=0;i< n;i++){
            int pos = tails.size();
            int low = 0;
            int high = tails.size()-1;
            while(low<=high){
                int mid = (high+low)/2;
                if(tails[mid] < nums[i]){
                    low = mid+1;
                } else {
                    pos=mid;
                    high = mid-1 ;
                }
            }
            if(pos == tails.size()){
                tails.push_back(nums[i]);
            } else {
                 tails[pos]= nums[i];
            }
        }
        return tails.size();

    }    
};
```

